<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'
import { adminApi } from '../api/admin'
const users=ref<any[]>([]);const roles=ref<any[]>([]);const q=ref('');const error=ref('');const page=ref(1);const pageSize=ref(10);const total=ref(0);const selected=ref<any>(null);const selectedRole=ref('')
const totalPages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)))
async function load(){try{const r=(await adminApi.users(q.value,pageSize.value,(page.value-1)*pageSize.value)).data.data;users.value=r.items;total.value=r.total;roles.value=(await adminApi.roles()).data.data}catch(e:any){error.value=e.response?.data?.detail||e.message}}
function search(){page.value=1;load()}
function jump(){page.value=Math.min(Math.max(page.value,1),totalPages.value);load()}
function changeSize(){page.value=1;load()}
async function toggleStatus(u:any){try{await adminApi.updateStatus(u.id,u.status==='active'?'disabled':'active');await load()}catch(e:any){error.value=e.response?.data?.detail||e.message}}
function openUserRole(u:any){selected.value=u;selectedRole.value=u.roles[0]||''}
async function saveRole(){if(!selected.value)return;try{await adminApi.updateRoles(selected.value.id,[selectedRole.value]);await load();selected.value=null}catch(e:any){error.value=e.response?.data?.detail||e.message}}
onMounted(load)
</script>
<template><section class="admin-table-page"><div class="section-heading"><div><span class="eyebrow">ADMINISTRATION</span><h2>用户与权限</h2></div><span class="pill">超级管理员</span></div><p v-if="error" class="error">{{error}}</p><div class="admin-toolbar"><input v-model="q" placeholder="搜索用户名或姓名" @keyup.enter="search"/><button class="button" @click="search">搜索</button><label>每页<select v-model.number="pageSize" @change="changeSize"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select>条</label></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>用户名</th><th>姓名</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.username}}</td><td>{{u.display_name}}</td><td><span v-for="r in u.roles" :key="r" class="table-tag">{{r}}</span></td><td>{{u.status}}</td><td><button class="table-action" @click="openUserRole(u)">修改角色</button><button class="table-action danger" @click="toggleStatus(u)">{{u.status==='active'?'禁用':'启用'}}</button></td></tr><tr v-if="!users.length"><td colspan="5" class="table-empty">暂无用户</td></tr></tbody></table></div><div class="admin-pagination"><button :disabled="page<=1" @click="page--;load()">上一页</button><span>第 {{page}} / {{totalPages}} 页，共 {{total}} 条</span><input v-model.number="page" type="number" min="1" :max="totalPages" @keyup.enter="jump"/><button @click="jump">跳转</button><button :disabled="page>=totalPages" @click="page++;load()">下一页</button></div><div v-if="selected" class="admin-modal-backdrop" @click.self="selected=null"><div class="admin-modal"><h3>修改角色：{{selected.username}}</h3><select v-model="selectedRole"><option v-for="role in roles" :key="role.code" :value="role.code">{{role.name}}（{{role.code}}）</option></select><div class="action-row"><button class="button" @click="saveRole">保存</button><button class="text-button" @click="selected=null">取消</button></div></div></div></section></template>
